// 转换自 changes/v1.3.0-log-partition-backup.xml (liquibase-kotlin 4.33.0-0.10.1)
// changeSet id/author 逐字保留；本文件为编译期 changelog，路径 = 类 FQCN。
package db.changelog.changes

import momosetkn.liquibase.kotlin.parser.KotlinCompiledDatabaseChangeLog

class V130LogPartitionBackup :
  KotlinCompiledDatabaseChangeLog({
    // =======================================================================
    // v1.3.0 日志离线备份(F-SYS-006):
    //       1) 三张日志表(api_logs / business_logs / user_action_logs)转为按月 RANGE 分区,
    //          主键由 (id) 改为 (id, created_at),id 保持 GENERATED BY DEFAULT AS IDENTITY;
    //       2) 新建归档 schema log_archive(按年份组织的冷表由服务侧懒建);
    //       3) 新建离线备份记录表 log_backup_records。
    //       说明:仅 PostgreSQL 生效(changeSet dbms="postgresql" 强制,测试库/其他库整体跳过);
    //       全部步骤置于单个 changeSet 内,利用 PG 事务性 DDL 保证原子性。DO $$ 动态建分区块
    //       必须 splitStatements="false"(Liquibase SQL 分割器不识别 dollar 引用,否则会在分区块
    //       内部的 ";" 处截断,PG 驱动报 "Unterminated dollar quote";交由 PG 驱动整体解析)。
    // =======================================================================
    changeSet(author = "aqua-rush", id = "v1.3.0-log-partition-backup", dbms = "postgresql") {
      // 修复存量漂移(该缺陷在 XML 时代就存在,全新库上必失败):日志分区改造(三张日志表+log_archive+log_backup_records)已整体被就地并入 v1.0.0 的 raw SQL
      preConditions(onFail = "MARK_RAN", onErrorMessage = "log_backup_records 已存在,跳过") {
        not {
          tableExists(tableName = "log_backup_records")
        }
      }
      comment(
        "Convert log tables to monthly range partitions + create log_archive schema and log_backup_records (PRD 11-system-settings.md F-SYS-006)",
      )
      sql(
        sql = """
      
      CREATE SCHEMA IF NOT EXISTS log_archive;
      
    
            """,
      )
      // ==================== api_logs ====================
      sql(
        sql = """
      
      ALTER TABLE api_logs RENAME TO api_logs_legacy;
      ALTER TABLE api_logs_legacy RENAME CONSTRAINT api_logs_pkey TO api_logs_legacy_pkey;
      ALTER TABLE api_logs_legacy ALTER COLUMN id DROP IDENTITY IF EXISTS;
      DROP INDEX IF EXISTS idx_api_logs_correlation_id;
      DROP INDEX IF EXISTS idx_api_logs_request_type;
      DROP INDEX IF EXISTS idx_api_logs_created_at;
      DROP INDEX IF EXISTS idx_api_logs_user_id;
      DROP INDEX IF EXISTS idx_api_logs_response_status;
      DROP INDEX IF EXISTS idx_api_logs_operation_type;
      DROP INDEX IF EXISTS idx_api_logs_operation_name;
      
    
            """,
      )
      sql(
        sql = """
      
      CREATE TABLE api_logs (
        id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
        correlation_id varchar(50),
        request_type varchar(20) NOT NULL,
        method varchar(10),
        uri varchar(500),
        query text,
        request_body text,
        response_status int,
        duration_ms bigint,
        ip_address varchar(50),
        user_agent varchar(500),
        user_id bigint,
        username varchar(100),
        error_message text,
        operation_type varchar(20),
        operation_name varchar(100),
        created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT api_logs_pkey PRIMARY KEY (id, created_at)
      ) PARTITION BY RANGE (created_at);

      CREATE TABLE api_logs_default PARTITION OF api_logs DEFAULT;

      CREATE INDEX idx_api_logs_correlation_id ON api_logs (correlation_id);
      CREATE INDEX idx_api_logs_request_type ON api_logs (request_type);
      CREATE INDEX idx_api_logs_created_at ON api_logs (created_at);
      CREATE INDEX idx_api_logs_user_id ON api_logs (user_id);
      CREATE INDEX idx_api_logs_response_status ON api_logs (response_status);
      CREATE INDEX idx_api_logs_operation_type ON api_logs (operation_type);
      CREATE INDEX idx_api_logs_operation_name ON api_logs (operation_name);
      
    
            """,
      )
      sql(
        sql = """
      
      DO ${'$'}${'$'}
      DECLARE m date;
      BEGIN
        FOR m IN
          SELECT generate_series(
                   date_trunc('month', min(created_at))::date,
                   date_trunc('month', now())::date + interval '1 month',
                   interval '1 month')::date
          FROM api_logs_legacy
        LOOP
          EXECUTE format(
            'CREATE TABLE IF NOT EXISTS api_logs_%s PARTITION OF api_logs FOR VALUES FROM (%L) TO (%L)',
            to_char(m, 'YYYY_MM'), m::timestamp, (m + interval '1 month'));
        END LOOP;
      END ${'$'}${'$'};
      
    
            """,
        splitStatements = false,
      )
      sql(
        sql = """
      
      INSERT INTO api_logs (id, correlation_id, request_type, method, uri, query, request_body, response_status, duration_ms, ip_address, user_agent, user_id, username, error_message, operation_type, operation_name, created_at)
      SELECT id, correlation_id, request_type, method, uri, query, request_body, response_status, duration_ms, ip_address, user_agent, user_id, username, error_message, operation_type, operation_name, created_at
      FROM api_logs_legacy;

      DROP TABLE api_logs_legacy;
      
    
            """,
      )
      // ==================== business_logs ====================
      sql(
        sql = """
      
      ALTER TABLE business_logs RENAME TO business_logs_legacy;
      ALTER TABLE business_logs_legacy RENAME CONSTRAINT business_logs_pkey TO business_logs_legacy_pkey;
      ALTER TABLE business_logs_legacy RENAME CONSTRAINT chk_log_level_valid TO chk_log_level_valid_legacy;
      ALTER TABLE business_logs_legacy ALTER COLUMN id DROP IDENTITY IF EXISTS;
      DROP INDEX IF EXISTS idx_business_logs_correlation_id;
      DROP INDEX IF EXISTS idx_business_logs_level;
      DROP INDEX IF EXISTS idx_business_logs_created_at;
      DROP INDEX IF EXISTS idx_business_logs_user_id;
      DROP INDEX IF EXISTS idx_business_logs_logger_name;
      
    
            """,
      )
      sql(
        sql = """
      
      CREATE TABLE business_logs (
        id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
        correlation_id varchar(50),
        level varchar(10) NOT NULL,
        logger_name varchar(200),
        message text,
        stack_trace text,
        user_id bigint,
        username varchar(100),
        created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
        operation varchar(100),
        CONSTRAINT business_logs_pkey PRIMARY KEY (id, created_at),
        CONSTRAINT chk_log_level_valid CHECK (level IN ('TRACE', 'DEBUG', 'INFO', 'WARN', 'ERROR'))
      ) PARTITION BY RANGE (created_at);

      CREATE TABLE business_logs_default PARTITION OF business_logs DEFAULT;

      CREATE INDEX idx_business_logs_correlation_id ON business_logs (correlation_id);
      CREATE INDEX idx_business_logs_level ON business_logs (level);
      CREATE INDEX idx_business_logs_created_at ON business_logs (created_at);
      CREATE INDEX idx_business_logs_user_id ON business_logs (user_id);
      CREATE INDEX idx_business_logs_logger_name ON business_logs (logger_name);
      
    
            """,
      )
      sql(
        sql = """
      
      DO ${'$'}${'$'}
      DECLARE m date;
      BEGIN
        FOR m IN
          SELECT generate_series(
                   date_trunc('month', min(created_at))::date,
                   date_trunc('month', now())::date + interval '1 month',
                   interval '1 month')::date
          FROM business_logs_legacy
        LOOP
          EXECUTE format(
            'CREATE TABLE IF NOT EXISTS business_logs_%s PARTITION OF business_logs FOR VALUES FROM (%L) TO (%L)',
            to_char(m, 'YYYY_MM'), m::timestamp, (m + interval '1 month'));
        END LOOP;
      END ${'$'}${'$'};
      
    
            """,
        splitStatements = false,
      )
      sql(
        sql = """
      
      INSERT INTO business_logs (id, correlation_id, level, logger_name, message, stack_trace, user_id, username, created_at, operation)
      SELECT id, correlation_id, level, logger_name, message, stack_trace, user_id, username, created_at, operation
      FROM business_logs_legacy;

      DROP TABLE business_logs_legacy;
      
    
            """,
      )
      // ==================== user_action_logs ====================
      sql(
        sql = """
      
      ALTER TABLE user_action_logs RENAME TO user_action_logs_legacy;
      ALTER TABLE user_action_logs_legacy RENAME CONSTRAINT user_action_logs_pkey TO user_action_logs_legacy_pkey;
      ALTER TABLE user_action_logs_legacy ALTER COLUMN id DROP IDENTITY IF EXISTS;
      DROP INDEX IF EXISTS idx_user_action_logs_user_id;
      DROP INDEX IF EXISTS idx_user_action_logs_action_type;
      DROP INDEX IF EXISTS idx_user_action_logs_created_at;
      
    
            """,
      )
      sql(
        sql = """
      
      CREATE TABLE user_action_logs (
        id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
        user_id varchar(50),
        username varchar(100),
        action_type varchar(50) NOT NULL,
        target varchar(500),
        page_url varchar(1000),
        element_id varchar(100),
        element_type varchar(50),
        element_text varchar(200),
        client_ip varchar(50),
        user_agent varchar(500),
        properties text,
        created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT user_action_logs_pkey PRIMARY KEY (id, created_at)
      ) PARTITION BY RANGE (created_at);

      CREATE TABLE user_action_logs_default PARTITION OF user_action_logs DEFAULT;

      CREATE INDEX idx_user_action_logs_user_id ON user_action_logs (user_id);
      CREATE INDEX idx_user_action_logs_action_type ON user_action_logs (action_type);
      CREATE INDEX idx_user_action_logs_created_at ON user_action_logs (created_at);
      
    
            """,
      )
      sql(
        sql = """
      
      DO ${'$'}${'$'}
      DECLARE m date;
      BEGIN
        FOR m IN
          SELECT generate_series(
                   date_trunc('month', min(created_at))::date,
                   date_trunc('month', now())::date + interval '1 month',
                   interval '1 month')::date
          FROM user_action_logs_legacy
        LOOP
          EXECUTE format(
            'CREATE TABLE IF NOT EXISTS user_action_logs_%s PARTITION OF user_action_logs FOR VALUES FROM (%L) TO (%L)',
            to_char(m, 'YYYY_MM'), m::timestamp, (m + interval '1 month'));
        END LOOP;
      END ${'$'}${'$'};
      
    
            """,
        splitStatements = false,
      )
      sql(
        sql = """
      
      INSERT INTO user_action_logs (id, user_id, username, action_type, target, page_url, element_id, element_type, element_text, client_ip, user_agent, properties, created_at)
      SELECT id, user_id, username, action_type, target, page_url, element_id, element_type, element_text, client_ip, user_agent, properties, created_at
      FROM user_action_logs_legacy;

      DROP TABLE user_action_logs_legacy;
      
    
            """,
      )
      // ==================== log_backup_records ====================
      sql(
        sql = """
      
      CREATE TABLE log_backup_records (
        id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        log_table varchar(30) NOT NULL,
        partition_name varchar(100) NOT NULL,
        partition_month varchar(7) NOT NULL,
        cold_table_name varchar(200) NOT NULL,
        from_bound timestamp,
        to_bound timestamp,
        row_count bigint NOT NULL DEFAULT 0,
        file_path varchar(500),
        file_size_bytes bigint,
        file_checksum varchar(64),
        status varchar(20) NOT NULL,
        error_message text,
        operator_id bigint,
        operator_name varchar(100),
        started_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
        finished_at timestamp,
        created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
      );

      CREATE INDEX idx_log_backup_records_log_table ON log_backup_records (log_table);
      CREATE INDEX idx_log_backup_records_created_at ON log_backup_records (created_at);
      
    
            """,
      )
      rollback {
        sql(
          sql = """
        
        DROP TABLE IF EXISTS log_backup_records;
        DROP SCHEMA IF EXISTS log_archive CASCADE;
        
      
                """,
        )
      }
    }
  })
